<?php class Reservation{
public static function mine($uid){$s=db()->prepare("SELECT r.*,a.id activity_id,a.title,a.image_url,s.starts_at,s.duration_minutes,s.coach_name FROM reservations r JOIN sessions s ON s.id=r.session_id JOIN activities a ON a.id=s.activity_id WHERE r.user_id=? ORDER BY s.starts_at DESC");$s->execute([$uid]);return $s->fetchAll();}
public static function create($uid,$sid){$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT s.capacity,COUNT(r.id) used FROM sessions s LEFT JOIN reservations r ON r.session_id=s.id AND r.status<>'cancelled' WHERE s.id=? AND s.starts_at>NOW() GROUP BY s.id FOR UPDATE");$q->execute([$sid]);$x=$q->fetch();if(!$x||$x['used']>=$x['capacity']){$pdo->rollBack();return false;}$s=$pdo->prepare("INSERT INTO reservations(user_id,session_id,status) VALUES(?,?,'confirmed') ON DUPLICATE KEY UPDATE status='confirmed'");$s->execute([$uid,$sid]);$pdo->commit();return true;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();return false;}}
public static function cancel($id,$uid){$s=db()->prepare("UPDATE reservations r JOIN sessions s ON s.id=r.session_id SET r.status='cancelled' WHERE r.id=? AND r.user_id=? AND s.starts_at>NOW()");$s->execute([$id,$uid]);return $s->rowCount()>0;}
public static function all(){return db()->query("SELECT r.id,r.status,r.created_at,u.firstname,u.lastname,u.email,a.title,s.starts_at FROM reservations r JOIN users u ON u.id=r.user_id JOIN sessions s ON s.id=r.session_id JOIN activities a ON a.id=s.activity_id ORDER BY s.starts_at DESC LIMIT 100")->fetchAll();}
public static function setStatus($id,$status){if(!in_array($status,['confirmed','cancelled','completed'],true))return;$s=db()->prepare('UPDATE reservations SET status=? WHERE id=?');$s->execute([$status,$id]);}
}